BEGIN;
CREATE SCHEMA IF NOT EXISTS teaching_runtime;
ALTER TABLE teaching_runtime.ai_execution_audit ADD COLUMN IF NOT EXISTS provider_identifier text,ADD COLUMN IF NOT EXISTS route_key text,ADD COLUMN IF NOT EXISTS requested_reasoning text,ADD COLUMN IF NOT EXISTS resolved_reasoning text,ADD COLUMN IF NOT EXISTS attempt_count integer NOT NULL DEFAULT 0,ADD COLUMN IF NOT EXISTS fallback_depth integer NOT NULL DEFAULT 0,ADD COLUMN IF NOT EXISTS latency_ms bigint,ADD COLUMN IF NOT EXISTS input_tokens bigint NOT NULL DEFAULT 0,ADD COLUMN IF NOT EXISTS output_tokens bigint NOT NULL DEFAULT 0,ADD COLUMN IF NOT EXISTS total_tokens bigint NOT NULL DEFAULT 0,ADD COLUMN IF NOT EXISTS estimated_cost_microunits bigint,ADD COLUMN IF NOT EXISTS cost_status text,ADD COLUMN IF NOT EXISTS retry_count integer NOT NULL DEFAULT 0,ADD COLUMN IF NOT EXISTS validation_retry_count integer NOT NULL DEFAULT 0,ADD COLUMN IF NOT EXISTS cache_status text NOT NULL DEFAULT 'BYPASS',ADD COLUMN IF NOT EXISTS execution_metadata jsonb NOT NULL DEFAULT '{}'::jsonb;
CREATE INDEX IF NOT EXISTS teaching_ai_execution_audit_correlation_idx ON teaching_runtime.ai_execution_audit(correlation_id,started_at DESC);CREATE INDEX IF NOT EXISTS teaching_ai_execution_audit_responsibility_idx ON teaching_runtime.ai_execution_audit(responsibility_key,started_at DESC);
CREATE TABLE IF NOT EXISTS teaching_runtime.d28_operational_events(event_id text PRIMARY KEY,category text NOT NULL,event_name text NOT NULL,severity text NOT NULL CHECK(severity IN('INFO','WARNING','CRITICAL')),correlation_id text,causation_id text,source_owner text,source_entity_type text,source_entity_id text,source_version text,outcome text,latency_ms bigint CHECK(latency_ms IS NULL OR latency_ms>=0),input_tokens bigint CHECK(input_tokens IS NULL OR input_tokens>=0),output_tokens bigint CHECK(output_tokens IS NULL OR output_tokens>=0),total_tokens bigint CHECK(total_tokens IS NULL OR total_tokens>=0),estimated_cost_microunits bigint CHECK(estimated_cost_microunits IS NULL OR estimated_cost_microunits>=0),cost_status text,retry_count integer NOT NULL DEFAULT 0 CHECK(retry_count>=0),fallback_depth integer NOT NULL DEFAULT 0 CHECK(fallback_depth>=0),metadata jsonb NOT NULL DEFAULT '{}'::jsonb,policy_version text,occurred_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT d28_operational_events_metadata_no_cot CHECK(lower(metadata::text) NOT LIKE '%chain_of_thought%' AND lower(metadata::text) NOT LIKE '%hidden_reasoning%' AND lower(metadata::text) NOT LIKE '%raw_prompt%'));
CREATE INDEX IF NOT EXISTS d28_operational_events_time_idx ON teaching_runtime.d28_operational_events(occurred_at DESC);CREATE INDEX IF NOT EXISTS d28_operational_events_correlation_idx ON teaching_runtime.d28_operational_events(correlation_id,occurred_at DESC);CREATE INDEX IF NOT EXISTS d28_operational_events_source_idx ON teaching_runtime.d28_operational_events(source_owner,source_entity_type,source_entity_id,occurred_at DESC);
CREATE TABLE IF NOT EXISTS teaching_runtime.d28_operational_alerts(alert_id text PRIMARY KEY,alert_type text NOT NULL,severity text NOT NULL CHECK(severity IN('WARNING','CRITICAL')),correlation_id text,source_ref text,reason_code text NOT NULL,status text NOT NULL DEFAULT 'OPEN' CHECK(status IN('OPEN','ACKNOWLEDGED','RESOLVED')),details jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),acknowledged_at timestamptz,resolved_at timestamptz);CREATE UNIQUE INDEX IF NOT EXISTS d28_operational_alerts_open_dedupe_idx ON teaching_runtime.d28_operational_alerts(alert_type,correlation_id,reason_code) WHERE status='OPEN';CREATE INDEX IF NOT EXISTS d28_operational_alerts_status_idx ON teaching_runtime.d28_operational_alerts(status,severity,created_at DESC);
CREATE TABLE IF NOT EXISTS teaching_runtime.d28_rollout_controls(rollout_id text PRIMARY KEY,change_kind text NOT NULL CHECK(change_kind IN('PROMPT','MODEL_ROUTE','POLICY')),scope_ref text NOT NULL,from_version text,to_version text NOT NULL,state text NOT NULL CHECK(state IN('STAGED','ACTIVE','PAUSED','ROLLED_BACK','SUPERSEDED')),policy_version text NOT NULL,authorized_by text NOT NULL,reason text,transition_reason text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());CREATE INDEX IF NOT EXISTS d28_rollout_controls_scope_idx ON teaching_runtime.d28_rollout_controls(change_kind,scope_ref,created_at DESC);
CREATE TABLE IF NOT EXISTS teaching_runtime.d28_quality_sample_refs(sample_ref_id text PRIMARY KEY,sample_kind text NOT NULL,source_owner text NOT NULL,source_entity_type text NOT NULL,source_entity_id text NOT NULL,source_version text NOT NULL,correlation_id text,sampling_reason text NOT NULL,validation_state text NOT NULL,privacy_class text NOT NULL DEFAULT 'PSEUDONYMOUS_REFERENCE_ONLY',raw_student_content_stored boolean NOT NULL DEFAULT false CHECK(raw_student_content_stored=false),created_at timestamptz NOT NULL DEFAULT now());CREATE INDEX IF NOT EXISTS d28_quality_sample_refs_source_idx ON teaching_runtime.d28_quality_sample_refs(source_owner,source_entity_type,source_entity_id,source_version);
CREATE TABLE IF NOT EXISTS teaching_runtime.d28_item_analytics_runs(analytics_run_id text PRIMARY KEY,assessment_id text NOT NULL,assessment_package_id text NOT NULL,package_version integer NOT NULL CHECK(package_version>0),assessment_blueprint_id text NOT NULL,blueprint_version integer,policy_version text NOT NULL,sample_policy_ref text NOT NULL,administration_context jsonb NOT NULL DEFAULT '{}'::jsonb,state text NOT NULL CHECK(state IN('RUNNING','insufficient_data','descriptive_only','supported','FAILED')),sample_size integer NOT NULL DEFAULT 0 CHECK(sample_size>=0),created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz);CREATE INDEX IF NOT EXISTS d28_item_analytics_runs_package_idx ON teaching_runtime.d28_item_analytics_runs(assessment_package_id,package_version,created_at DESC);
CREATE TABLE IF NOT EXISTS teaching_runtime.d28_item_analytics_items(analytics_item_id text PRIMARY KEY,analytics_run_id text NOT NULL REFERENCES teaching_runtime.d28_item_analytics_runs(analytics_run_id) ON DELETE CASCADE,package_item_id text NOT NULL,candidate_version_id text NOT NULL,slot_id text NOT NULL,item_hash text,locked_option_order jsonb NOT NULL DEFAULT '[]'::jsonb,sample_size integer NOT NULL CHECK(sample_size>=0),sufficiency_state text NOT NULL CHECK(sufficiency_state IN('insufficient_data','descriptive_only','supported','not_applicable')),facility double precision,facility_interpretation text NOT NULL,discrimination_method text NOT NULL,discrimination_value double precision,omission_count integer NOT NULL CHECK(omission_count>=0),omission_rate double precision,distractor_summary jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());CREATE INDEX IF NOT EXISTS d28_item_analytics_items_lineage_idx ON teaching_runtime.d28_item_analytics_items(package_item_id,candidate_version_id,analytics_run_id);
CREATE TABLE IF NOT EXISTS teaching_runtime.d28_item_analytics_review_flags(review_flag_id text PRIMARY KEY,analytics_run_id text NOT NULL REFERENCES teaching_runtime.d28_item_analytics_runs(analytics_run_id) ON DELETE CASCADE,package_item_id text NOT NULL,flag_code text NOT NULL,status text NOT NULL CHECK(status IN('OPEN','REVIEWED','DISMISSED','ROUTED_TPF14')),academic_action_taken boolean NOT NULL DEFAULT false CHECK(academic_action_taken=false),review_note text,created_at timestamptz NOT NULL DEFAULT now(),reviewed_at timestamptz);CREATE INDEX IF NOT EXISTS d28_item_analytics_review_flags_open_idx ON teaching_runtime.d28_item_analytics_review_flags(status,created_at DESC);
CREATE TABLE IF NOT EXISTS teaching_runtime.d28_ppl_budget_usage(usage_id text PRIMARY KEY,workspace_id text NOT NULL,workspace_version bigint NOT NULL,policy_version text NOT NULL,route_posture text,disposition text NOT NULL,material_noop boolean NOT NULL DEFAULT false,model_calls integer NOT NULL DEFAULT 0 CHECK(model_calls>=0),total_tokens bigint NOT NULL DEFAULT 0 CHECK(total_tokens>=0),estimated_cost_microunits bigint CHECK(estimated_cost_microunits IS NULL OR estimated_cost_microunits>=0),latency_ms bigint CHECK(latency_ms IS NULL OR latency_ms>=0),provenance jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT d28_ppl_provenance_no_cot CHECK(lower(provenance::text) NOT LIKE '%chain_of_thought%' AND lower(provenance::text) NOT LIKE '%hidden_reasoning%'));CREATE INDEX IF NOT EXISTS d28_ppl_budget_workspace_idx ON teaching_runtime.d28_ppl_budget_usage(workspace_id,workspace_version,created_at DESC);
CREATE TABLE IF NOT EXISTS teaching_runtime.d28_artifact_visibility_controls(control_id text PRIMARY KEY,student_id text NOT NULL,artifact_type text NOT NULL,artifact_id text NOT NULL,course_id text,subject_id text,visibility_state text NOT NULL CHECK(visibility_state IN('VISIBLE','SUPPRESSED','SOURCE_UNAVAILABLE','DELETED_BY_POLICY')),reason_code text NOT NULL,source_owner text NOT NULL,source_version text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(student_id,artifact_type,artifact_id));CREATE INDEX IF NOT EXISTS d28_artifact_visibility_course_idx ON teaching_runtime.d28_artifact_visibility_controls(student_id,course_id,visibility_state);
CREATE TABLE IF NOT EXISTS teaching_runtime.d28_retention_actions(retention_action_id text PRIMARY KEY,policy_version text NOT NULL,student_id text,artifact_type text NOT NULL,artifact_id text NOT NULL,action_kind text NOT NULL,preserved_academic_lineage boolean NOT NULL DEFAULT true CHECK(preserved_academic_lineage=true),reason_code text NOT NULL,executed_at timestamptz NOT NULL DEFAULT now());CREATE INDEX IF NOT EXISTS d28_retention_actions_artifact_idx ON teaching_runtime.d28_retention_actions(artifact_type,artifact_id,executed_at DESC);
CREATE TABLE IF NOT EXISTS teaching_runtime.d28_ai_response_cache(cache_key text PRIMARY KEY,capability_id text NOT NULL,authority_level text NOT NULL CHECK(authority_level IN('T1','T2')),prompt_version text,schema_version text,source_version_digest text NOT NULL,payload jsonb NOT NULL,personalized boolean NOT NULL DEFAULT false CHECK(personalized=false),authoritative_judgment boolean NOT NULL DEFAULT false CHECK(authoritative_judgment=false),protected_content boolean NOT NULL DEFAULT false CHECK(protected_content=false),created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL);CREATE INDEX IF NOT EXISTS d28_ai_response_cache_expiry_idx ON teaching_runtime.d28_ai_response_cache(expires_at);
CREATE OR REPLACE FUNCTION teaching_runtime.d28_capture_minimized_mutation() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,teaching_runtime AS $$DECLARE payload jsonb:=CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;entity_id text;version_ref text;BEGIN entity_id:=payload->>TG_ARGV[2];version_ref:=CASE WHEN TG_NARGS>=4 THEN payload->>TG_ARGV[3] ELSE NULL END;BEGIN INSERT INTO teaching_runtime.d28_operational_events(event_id,category,event_name,severity,source_owner,source_entity_type,source_entity_id,source_version,outcome,metadata,policy_version,occurred_at) VALUES(gen_random_uuid()::text,TG_ARGV[0],TG_ARGV[1],'INFO',TG_TABLE_NAME,TG_TABLE_NAME,entity_id,version_ref,TG_OP,jsonb_build_object('databaseMutation',true,'table',TG_TABLE_NAME,'operation',TG_OP),'teaching.d28.operational-hardening.v1',now());EXCEPTION WHEN OTHERS THEN NULL;END;RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;END$$;
DROP TRIGGER IF EXISTS d28_observe_class_session ON public.teaching_class_sessions;CREATE TRIGGER d28_observe_class_session AFTER INSERT OR UPDATE ON public.teaching_class_sessions FOR EACH ROW EXECUTE FUNCTION teaching_runtime.d28_capture_minimized_mutation('CONTROLLER_TRANSITION','class_session_transition','class_session_id','state_version');DROP TRIGGER IF EXISTS d28_observe_timetable ON public.teaching_timetable_versions;CREATE TRIGGER d28_observe_timetable AFTER INSERT OR UPDATE ON public.teaching_timetable_versions FOR EACH ROW EXECUTE FUNCTION teaching_runtime.d28_capture_minimized_mutation('SCHEDULE','timetable_version_change','timetable_version_id','version_no');DROP TRIGGER IF EXISTS d28_observe_schedule_feasibility ON public.teaching_schedule_feasibility;CREATE TRIGGER d28_observe_schedule_feasibility AFTER INSERT OR UPDATE ON public.teaching_schedule_feasibility FOR EACH ROW EXECUTE FUNCTION teaching_runtime.d28_capture_minimized_mutation('SCHEDULE','schedule_feasibility_change','feasibility_id');DROP TRIGGER IF EXISTS d28_observe_assessment_package ON public.teaching_assessment_packages;CREATE TRIGGER d28_observe_assessment_package AFTER INSERT OR UPDATE ON public.teaching_assessment_packages FOR EACH ROW EXECUTE FUNCTION teaching_runtime.d28_capture_minimized_mutation('ASSESSMENT','assessment_package_change','assessment_package_id','version_no');DROP TRIGGER IF EXISTS d28_observe_assessment_response ON public.teaching_assessment_responses;CREATE TRIGGER d28_observe_assessment_response AFTER INSERT ON public.teaching_assessment_responses FOR EACH ROW EXECUTE FUNCTION teaching_runtime.d28_capture_minimized_mutation('AUTOSAVE','assessment_response_server_persisted','assessment_response_id','response_version');DROP TRIGGER IF EXISTS d28_observe_marking_run ON public.teaching_marking_runs;CREATE TRIGGER d28_observe_marking_run AFTER INSERT OR UPDATE ON public.teaching_marking_runs FOR EACH ROW EXECUTE FUNCTION teaching_runtime.d28_capture_minimized_mutation('MARKING','marking_run_change','marking_run_id');DROP TRIGGER IF EXISTS d28_observe_gradebook ON public.teaching_gradebook_entries;CREATE TRIGGER d28_observe_gradebook AFTER INSERT ON public.teaching_gradebook_entries FOR EACH ROW EXECUTE FUNCTION teaching_runtime.d28_capture_minimized_mutation('GRADEBOOK','gradebook_entry_committed','gradebook_entry_id');DROP TRIGGER IF EXISTS d28_observe_grade_change ON public.teaching_grade_change_audit;CREATE TRIGGER d28_observe_grade_change AFTER INSERT ON public.teaching_grade_change_audit FOR EACH ROW EXECUTE FUNCTION teaching_runtime.d28_capture_minimized_mutation('GRADEBOOK','grade_change_audit','grade_change_audit_id');
REVOKE ALL ON ALL TABLES IN SCHEMA teaching_runtime FROM PUBLIC,anon,authenticated;GRANT USAGE ON SCHEMA teaching_runtime TO service_role;GRANT SELECT,INSERT,UPDATE,DELETE ON teaching_runtime.d28_operational_events,teaching_runtime.d28_operational_alerts,teaching_runtime.d28_rollout_controls,teaching_runtime.d28_quality_sample_refs,teaching_runtime.d28_item_analytics_runs,teaching_runtime.d28_item_analytics_items,teaching_runtime.d28_item_analytics_review_flags,teaching_runtime.d28_ppl_budget_usage,teaching_runtime.d28_artifact_visibility_controls,teaching_runtime.d28_retention_actions,teaching_runtime.d28_ai_response_cache TO service_role;
ALTER TABLE teaching_runtime.d28_operational_events ENABLE ROW LEVEL SECURITY;ALTER TABLE teaching_runtime.d28_operational_alerts ENABLE ROW LEVEL SECURITY;ALTER TABLE teaching_runtime.d28_rollout_controls ENABLE ROW LEVEL SECURITY;ALTER TABLE teaching_runtime.d28_quality_sample_refs ENABLE ROW LEVEL SECURITY;ALTER TABLE teaching_runtime.d28_item_analytics_runs ENABLE ROW LEVEL SECURITY;ALTER TABLE teaching_runtime.d28_item_analytics_items ENABLE ROW LEVEL SECURITY;ALTER TABLE teaching_runtime.d28_item_analytics_review_flags ENABLE ROW LEVEL SECURITY;ALTER TABLE teaching_runtime.d28_ppl_budget_usage ENABLE ROW LEVEL SECURITY;ALTER TABLE teaching_runtime.d28_artifact_visibility_controls ENABLE ROW LEVEL SECURITY;ALTER TABLE teaching_runtime.d28_retention_actions ENABLE ROW LEVEL SECURITY;ALTER TABLE teaching_runtime.d28_ai_response_cache ENABLE ROW LEVEL SECURITY;
COMMIT;
